<div id="docara-reader-settings-dialog" popover data-docara-reader-settings-dialog data-docara-reader-settings-menu data-docara-transient-dialog class="docara-preferences-menu sf-context-menu"><section data-docara-smart="docara.preferences" data-docara-view="menu" role="menu" aria-labelledby="docara-reader-settings-title" class="sf-context-menu-content flex flex-col flex-1 min-w-0"><h2 id="docara-reader-settings-title" class="sr-only"><?= $view->title ?></h2>
<div class="docara-preferences-menu__group flex flex-col"><?php foreach ($view->groups as $group) { ?><?php foreach ($group['fields'] as $field) { ?><?php $current = '';
    foreach ($field['options'] as $option) {
        if ($option['selected']) {
            $current = $option['title'];
        }
    } ?><div class="docara-preferences-menu__entry" data-docara-preference-field="<?= $field['id'] ?>"><button type="button" role="menuitem" aria-haspopup="menu" aria-expanded="false" aria-controls="docara-preference-menu-<?= $field['id'] ?>" tabindex="-1" data-docara-preference-submenu-trigger class="docara-preferences-menu__item sf-button sf-button--link sf-button--on-surface sf-button--size-1 flex items-cross-center"><sf-icon icon="<?= ['appearance.theme' => 'contrast', 'appearance.font_size' => 'format_size', 'appearance.content_width' => 'width_normal'][$field['id']] ?? 'tune' ?>" aria-hidden="true"></sf-icon><span id="docara-preference-label-<?= $field['id'] ?>" class="sf-button-text-container docara-preferences-label"><?= $field['title'] ?></span><span class="docara-preferences-menu__value" data-docara-preference-value><?= $current ?></span><sf-icon class="docara-preferences-menu__chevron" icon="chevron_right" aria-hidden="true"></sf-icon></button><div id="docara-preference-menu-<?= $field['id'] ?>" role="menu" aria-labelledby="docara-preference-label-<?= $field['id'] ?>" hidden data-docara-preference-submenu class="docara-preferences-submenu sf-context-menu"><div class="sf-context-menu-content flex flex-col"><?php foreach ($field['options'] as $option) { ?><button type="button" role="menuitemradio" aria-checked="<?= $option['selected'] ? 'true' : 'false' ?>" tabindex="-1" data-docara-preference-option data-preference-id="<?= $field['id'] ?>" value="<?= $option['value'] ?>" class="docara-preferences-menu__item sf-button sf-button--link sf-button--on-surface sf-button--size-1 flex items-cross-center"><span class="sf-button-text-container"><?= $option['title'] ?></span><sf-icon class="docara-preferences-menu__check" icon="check" aria-hidden="true"></sf-icon></button><?php } ?></div></div></div><?php } ?><?php } ?></div>
<div class="docara-preferences-menu__group flex flex-col"><button type="button" role="menuitem" tabindex="-1" data-docara-reader-settings-reset class="docara-preferences-menu__item sf-button sf-button--link sf-button--on-surface sf-button--size-1 flex items-cross-center"><sf-icon icon="restart_alt" aria-hidden="true"></sf-icon><span class="sf-button-text-container"><?= $view->resetLabel ?></span></button></div>
<p id="docara-reader-settings-status" data-docara-reader-settings-status class="sr-only" aria-live="polite"></p></section></div>
